$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
$Root = (Get-Location).Path
$OutDir = Join-Path $Root 'docs/miyake-yuko/img/tiktok-assets/variants-10-paired-characters'
$TokaDir = Join-Path $Root 'docs/miyake-yuko/img/8mobby-toka'
New-Item -ItemType Directory -Path $OutDir -Force | Out-Null
function BrushX($hex){ New-Object Drawing.SolidBrush ([Drawing.ColorTranslator]::FromHtml($hex)) }
function PenX($hex,$w){ $pen=New-Object Drawing.Pen ([Drawing.ColorTranslator]::FromHtml($hex)), $w; $pen.StartCap='Round'; $pen.EndCap='Round'; return $pen }
function FontX($name,$size,$style='Regular'){ try { New-Object Drawing.Font($name,$size,[Drawing.FontStyle]::$style,[Drawing.GraphicsUnit]::Pixel) } catch { New-Object Drawing.Font('Yu Gothic UI',$size,[Drawing.FontStyle]::$style,[Drawing.GraphicsUnit]::Pixel) } }
function RoundX($g,$x,$y,$w,$h,$r,$fill,$stroke=$null){ $path=New-Object Drawing.Drawing2D.GraphicsPath; $d=$r*2; $path.AddArc($x,$y,$d,$d,180,90); $path.AddArc($x+$w-$d,$y,$d,$d,270,90); $path.AddArc($x+$w-$d,$y+$h-$d,$d,$d,0,90); $path.AddArc($x,$y+$h-$d,$d,$d,90,90); $path.CloseFigure(); if($fill){$g.FillPath($fill,$path)}; if($stroke){$g.DrawPath($stroke,$path)}; $path.Dispose() }
function TextX($g,$text,$font,$brush,$x,$y,$w,$h,$align='Center'){ $sf=New-Object Drawing.StringFormat; $sf.Alignment=[Drawing.StringAlignment]::$align; $sf.LineAlignment='Center'; $sf.Trimming='EllipsisCharacter'; $g.DrawString($text,$font,$brush,(New-Object Drawing.RectangleF $x,$y,$w,$h),$sf); $sf.Dispose() }
function ImageFit($g,$path,$x,$y,$w,$h,$rot=0){ $img=[Drawing.Image]::FromFile($path); $scale=[Math]::Min($w/$img.Width,$h/$img.Height); $dw=$img.Width*$scale; $dh=$img.Height*$scale; $state=$g.Save(); $g.TranslateTransform($x+$w/2,$y+$h/2); if($rot -ne 0){$g.RotateTransform($rot)}; $g.DrawImage($img,-$dw/2,-$dh/2,$dw,$dh); $g.Restore($state); $img.Dispose() }
function HeaderX($g,$sub){ TextX $g 'ペアキャラ紹介' $Title (BrushX '#e94d7a') 70 34 940 72; TextX $g $sub $Sub (BrushX '#3b2929') 100 104 880 36 }
function FooterX($g){ RoundX $g 130 1418 820 42 21 (BrushX '#fffdfb') (PenX '#f39bb5' 2); TextX $g 'モビーとパートナーを一緒に紹介' $Foot (BrushX '#e94d7a') 145 1420 790 38 }
function PairCard($g,$item,$x,$y,$w,$h,$color,$fill,$imgW=170,$imgH=150){ RoundX $g $x $y $w $h 28 (BrushX $fill) (PenX $color 4); ImageFit $g $item.FullName ($x+12) ($y+12) $imgW $imgH 0; TextX $g $item.BaseName $Label (BrushX $color) ($x+$imgW+28) ($y+28) ($w-$imgW-42) 60 'Near'; TextX $g 'モビー + パートナー' $Small (BrushX '#4a3636') ($x+$imgW+28) ($y+92) ($w-$imgW-42) 34 'Near' }
$Title=FontX 'HGP創英角ﾎﾟｯﾌﾟ体' 62 'Bold'; $Sub=FontX 'HG丸ｺﾞｼｯｸM-PRO' 24 'Bold'; $Label=FontX 'HG丸ｺﾞｼｯｸM-PRO' 24 'Bold'; $Small=FontX 'HG丸ｺﾞｼｯｸM-PRO' 18 'Bold'; $Foot=FontX 'HG丸ｺﾞｼｯｸM-PRO' 19 'Bold'; $Comic=FontX 'Comic Sans MS' 30 'Bold'
$Items=Get-ChildItem -LiteralPath $TokaDir -Filter '*.png' | Sort-Object Name
$Colors=@('#e94d7a','#ff8a25','#27a879','#219fb0','#6e63d8','#9b66de','#d29a39','#ef6f91')
$Subtitles=@('PAIR LOOKBOOK','K-BEAUTY PARTNERS','PHOTO BOOTH PAIRS','CAST LINEUP','COSME SHOP PAIRS','PROFILE CARDS','STICKER PAIRS','ORBIT MAP','MINI APP LIST','PAIR STAGE')
for($v=1;$v -le 10;$v++){
  $bmp=New-Object Drawing.Bitmap 1080,1500; $g=[Drawing.Graphics]::FromImage($bmp); $g.SmoothingMode='AntiAlias'; $g.TextRenderingHint='AntiAliasGridFit'; $g.Clear([Drawing.ColorTranslator]::FromHtml('#fff4df'))
  HeaderX $g $Subtitles[$v-1]
  switch($v){
    1 { for($i=0;$i -lt 8;$i++){ $col=$i%2; $row=[math]::Floor($i/2); PairCard $g $Items[$i] (70+$col*490) (175+$row*290) 440 245 $Colors[$i] '#fffdfb' 178 152 } }
    2 { RoundX $g 65 170 950 1090 42 (BrushX '#fffdfb') (PenX '#f4b4c7' 5); for($i=0;$i -lt 8;$i++){ $x=100+($i%4)*220; $y=230+[math]::Floor($i/4)*430; RoundX $g $x $y 185 340 30 (BrushX '#fff7fb') (PenX $Colors[$i] 3); ImageFit $g $Items[$i].FullName ($x+8) ($y+20) 170 210 0; TextX $g $Items[$i].BaseName $Label (BrushX $Colors[$i]) ($x+13) ($y+240) 160 58; TextX $g 'PAIR' $Comic (BrushX '#4a3636') ($x+18) ($y+298) 150 28 } }
    3 { for($i=0;$i -lt 4;$i++){ RoundX $g (95+$i*225) 170 190 500 28 (BrushX '#ffffff') (PenX '#f3adc1' 4); ImageFit $g $Items[$i].FullName (105+$i*225) 205 170 210 (($i%2)*7-3); TextX $g $Items[$i].BaseName $Label (BrushX $Colors[$i]) (110+$i*225) 440 160 80 }; for($i=4;$i -lt 8;$i++){ RoundX $g (95+($i-4)*225) 740 190 500 28 (BrushX '#ffffff') (PenX '#a8dce8' 4); ImageFit $g $Items[$i].FullName (105+($i-4)*225) 775 170 210 (($i%2)*7-3); TextX $g $Items[$i].BaseName $Label (BrushX $Colors[$i]) (110+($i-4)*225) 1010 160 80 } }
    4 { RoundX $g 70 180 940 1040 42 (BrushX '#ffe8f0') (PenX '#ffffff' 8); TextX $g 'BEAUTY PAIR CAST' $Comic (BrushX '#e94d7a') 100 215 880 54; for($i=0;$i -lt 8;$i++){ ImageFit $g $Items[$i].FullName (60+$i*123) (305+($i%2)*50) 150 180 (($i%3)-1)*5; TextX $g $Items[$i].BaseName (FontX 'HG丸ｺﾞｼｯｸM-PRO' 18 'Bold') (BrushX $Colors[$i]) (35+$i*123) 520 175 58 }; for($i=0;$i -lt 8;$i++){ PairCard $g $Items[$i] (90+($i%2)*465) (625+[math]::Floor($i/2)*150) 420 120 $Colors[$i] '#fffdfb' 95 92 } }
    5 { for($r=0;$r -lt 4;$r++){ RoundX $g 80 (235+$r*250) 920 135 28 (BrushX '#fffdfb') (PenX '#d6b77b' 4) }; for($i=0;$i -lt 8;$i++){ $x=95+($i%4)*230; $y=150+[math]::Floor($i/4)*500; ImageFit $g $Items[$i].FullName $x $y 190 190 0; TextX $g $Items[$i].BaseName $Label (BrushX $Colors[$i]) ($x-18) ($y+190) 225 50 } }
    6 { for($i=0;$i -lt 8;$i++){ $x=72+($i%2)*492; $y=175+[math]::Floor($i/2)*285; RoundX $g $x $y 445 240 36 (BrushX '#f8fffb') (PenX $Colors[$i] 4); TextX $g ('PAIR '+($i+1).ToString('00')) $Comic (BrushX $Colors[$i]) ($x+22) ($y+16) 150 36 'Near'; ImageFit $g $Items[$i].FullName ($x+22) ($y+58) 170 150 0; TextX $g $Items[$i].BaseName $Label (BrushX $Colors[$i]) ($x+205) ($y+62) 215 70 'Near'; TextX $g 'モビーと一緒' $Small (BrushX '#4a3636') ($x+205) ($y+142) 215 36 'Near' } }
    7 { for($i=0;$i -lt 8;$i++){ $x=80+(($i*233)%820); $y=185+(($i*163)%930); RoundX $g $x $y 260 220 34 (BrushX '#ffffff') (PenX $Colors[$i] 4); ImageFit $g $Items[$i].FullName ($x+18) ($y+18) 220 142 (($i%5)-2)*7; TextX $g $Items[$i].BaseName $Label (BrushX $Colors[$i]) ($x+15) ($y+160) 230 42 } }
    8 { RoundX $g 150 248 780 780 390 (BrushX '#fffdfb') (PenX '#f3adc1' 5); TextX $g 'PAIR MAP' $Comic (BrushX '#e94d7a') 390 610 300 58; for($i=0;$i -lt 8;$i++){ $angle=(-90+$i*45)*[Math]::PI/180; $x=475+[Math]::Cos($angle)*350; $y=610+[Math]::Sin($angle)*350; RoundX $g ($x-122) ($y-76) 244 152 36 (BrushX '#ffffff') (PenX $Colors[$i] 3); ImageFit $g $Items[$i].FullName ($x-105) ($y-60) 95 88 0; TextX $g $Items[$i].BaseName (FontX 'HG丸ｺﾞｼｯｸM-PRO' 16 'Bold') (BrushX $Colors[$i]) ($x-5) ($y-50) 110 96 'Near' } }
    9 { RoundX $g 180 170 720 1080 48 (BrushX '#ffffff') (PenX '#f5a9bf' 5); RoundX $g 225 215 630 82 41 (BrushX '#ffe8f0') $null; TextX $g 'Mobby Pair List' $Comic (BrushX '#e94d7a') 245 226 590 58; for($i=0;$i -lt 8;$i++){ PairCard $g $Items[$i] 225 (330+$i*105) 630 88 $Colors[$i] '#fffdfb' 92 66 } }
    10 { RoundX $g 70 185 940 1040 42 (BrushX '#f1fff4') (PenX '#b7e1c5' 5); TextX $g 'PAIR ALL STARS' $Comic (BrushX '#27a879') 100 220 880 60; for($i=0;$i -lt 8;$i++){ RoundX $g (100+($i%4)*220) (340+[math]::Floor($i/4)*165) 185 115 28 (BrushX '#ffffff') (PenX $Colors[$i] 3); TextX $g $Items[$i].BaseName (FontX 'HG丸ｺﾞｼｯｸM-PRO' 18 'Bold') (BrushX $Colors[$i]) (112+($i%4)*220) (360+[math]::Floor($i/4)*165) 160 70 }; for($i=0;$i -lt 8;$i++){ ImageFit $g $Items[$i].FullName (45+$i*126) (785+($i%2)*35) 158 198 (($i%3)-1)*5; TextX $g $Items[$i].BaseName (FontX 'HG丸ｺﾞｼｯｸM-PRO' 17 'Bold') (BrushX $Colors[$i]) (25+$i*126) 1020 178 54 } }
  }
  FooterX $g
  $file=Join-Path $OutDir ('paired-characters-{0:D2}-code.png' -f $v)
  $bmp.Save($file,[Drawing.Imaging.ImageFormat]::Png)
  $prompt="Use case: infographic-diagram. Asset type: TikTok vertical post. Create a paired character introduction image, design version $v. Korean cute K-beauty mood, yellow-cream base. Important: each design must show the Mobby character together with the human partner standing next to it as one pair, not separated. Introduce all eight pair images with names: グルメモビー, 美容インフルエンサーモビー, 美容エディターモビー, 美容研究家モビー, 透明感モデルモビー, 韓ドラ女優モビー, 韓国アイドルモビー, 韓国コスメコンシェルジュモビー. Title exactly ペアキャラ紹介. Use rounded kawaii Japanese typography, no diagnostic questions, no axes, no result explanation grid, no watermark."
  Set-Content -LiteralPath (Join-Path $OutDir ('paired-characters-{0:D2}-prompt.txt' -f $v)) -Value $prompt -Encoding UTF8
  $g.Dispose(); $bmp.Dispose()
}
Write-Output $OutDir
